// Genera nome file dinamico con timestamp
const now = new Date();
const day = String(now.getDate()).padStart(2, '0');
const month = String(now.getMonth() + 1).padStart(2, '0');
const year = now.getFullYear();
const hours = String(now.getHours()).padStart(2, '0');
const minutes = String(now.getMinutes()).padStart(2, '0');

const filename = `riassunto_${day}-${month}-${year}_${hours}-${minutes}.txt`;

// Recupera il testo del riassunto (LLM Chain output)
const summaryText = $input.first().json.text 
  || $input.first().json.response
  || $input.first().json.output
  || 'Errore: nessun riassunto generato.';

return [
  {
    json: {
      filename: filename,
      summaryText: summaryText,
      generatedAt: now.toISOString()
    }
  }
];

